package com.simibubi.create.test;

import com.simibubi.create.*;
import com.simibubi.create.api.contraption.BlockMovementChecks;
import com.simibubi.create.content.contraptions.glue.*;
import java.util.*;
import net.fabricmc.fabric.api.gametest.v1.GameTest;
import net.minecraft.core.*;
import net.minecraft.gametest.framework.GameTestHelper;
import net.minecraft.util.ProblemReporter;
import net.minecraft.world.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.*;
import net.minecraft.world.item.context.UseOnContext;
import net.minecraft.world.level.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.storage.*;
import net.minecraft.world.phys.*;

public class SuperGlueGameTests {
    private static final BlockPos P=new BlockPos(2,3,2),Q=P.east();
    private static Player player(GameTestHelper h){var player=h.makeMockPlayer(GameType.SURVIVAL);player.setPos(Vec3.atCenterOf(h.absolutePos(P)).add(0,0,3));player.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(AllItems.SUPER_GLUE));return player;}
    private static void stones(GameTestHelper h){h.setBlock(P,Blocks.STONE);h.setBlock(Q,Blocks.STONE);}
    private static SuperGlueEntity glue(GameTestHelper h){var glue=new SuperGlueEntity(h.getLevel(),SuperGlueEntity.span(h.absolutePos(P),h.absolutePos(Q)));h.getLevel().addFreshEntity(glue);return glue;}
    private static void aim(Player player,Vec3 point){var delta=point.subtract(player.getEyePosition());player.setYRot((float)Math.toDegrees(Math.atan2(-delta.x,delta.z)));player.setXRot((float)-Math.toDegrees(Math.atan2(delta.y,Math.hypot(delta.x,delta.z))));}
    private static List<SuperGlueEntity> nearby(GameTestHelper h){return h.getLevel().getEntitiesOfClass(SuperGlueEntity.class,new AABB(h.absolutePos(P)).inflate(8));}
    @GameTest public void areaSelectionCreatesOnePersistentVolumeAndUsesOneCharge(GameTestHelper h){stones(h);var player=player(h);h.assertTrue(SuperGlueHandler.select(player,new SuperGlueSelectionPacket(h.absolutePos(P),h.absolutePos(Q))),"Connected area accepted by server");h.assertValueEqual(player.getMainHandItem().getDamageValue(),1,"One glue charge");var entities=nearby(h);h.assertValueEqual(entities.size(),1,"Exactly one real glue entity");h.assertValueEqual(entities.getFirst().getBoundingBox(),SuperGlueEntity.span(h.absolutePos(P),h.absolutePos(Q)),"Whole source span");h.assertTrue(SuperGlueEntity.isGlued(h.getLevel(),h.absolutePos(P),Direction.EAST,null),"Forward glued face");h.assertTrue(SuperGlueEntity.isGlued(h.getLevel(),h.absolutePos(Q),Direction.WEST,null),"Reverse glued face");h.succeed();}
    @GameTest public void previewsAndInsufficientChargesNeverDamageInventory(GameTestHelper h){var player=player(h);var stack=player.getMainHandItem();stack.setDamageValue(98);for(int i=0;i<50;i++)h.assertTrue(SuperGlueSelectionHelper.collectGlueFromInventory(player,1,true),"Preview can afford last charge");h.assertValueEqual(stack.getDamageValue(),98,"Preview is read only");h.assertFalse(SuperGlueSelectionHelper.collectGlueFromInventory(player,2,false),"Cannot pay entire amount");h.assertValueEqual(stack.getDamageValue(),98,"No partial payment on refusal");h.assertTrue(SuperGlueSelectionHelper.collectGlueFromInventory(player,1,false),"Last real charge paid");h.assertTrue(player.getMainHandItem().isEmpty(),"Ninety-ninth charge breaks item");h.succeed();}
    @GameTest public void chargesCanBeCollectedAcrossSelectedAndOtherInventorySlots(GameTestHelper h){var player=player(h);player.getMainHandItem().setDamageValue(98);var second=new ItemStack(AllItems.SUPER_GLUE);second.setDamageValue(97);player.getInventory().setItem(9,second);h.assertTrue(SuperGlueSelectionHelper.collectGlueFromInventory(player,3,true),"Combined budget");h.assertValueEqual(second.getDamageValue(),97,"Simulation does not damage second stack");h.assertTrue(SuperGlueSelectionHelper.collectGlueFromInventory(player,2,false),"Uses selected charge first");h.assertTrue(player.getMainHandItem().isEmpty(),"Selected item used before inventory");h.assertValueEqual(second.getDamageValue(),98,"One charge from next item");h.succeed();}
    @GameTest public void disconnectedAndOversizeRequestsDoNotConsumeGlue(GameTestHelper h){h.setBlock(P,Blocks.STONE);h.setBlock(P.east(2),Blocks.STONE);var player=player(h);h.assertFalse(SuperGlueHandler.select(player,new SuperGlueSelectionPacket(h.absolutePos(P),h.absolutePos(P.east(2)))),"Air gap disconnects group");h.assertFalse(SuperGlueHandler.select(player,new SuperGlueSelectionPacket(h.absolutePos(P.west(25)),h.absolutePos(P))),"Source length limit is strict");h.assertValueEqual(player.getMainHandItem().getDamageValue(),0,"Refusals do not consume charges");h.assertTrue(nearby(h).isEmpty(),"No invalid area entity");h.succeed();}
    @GameTest public void wrongToolAndAdventureModeCannotForgeAreaPackets(GameTestHelper h){stones(h);var player=player(h);player.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);var packet=new SuperGlueSelectionPacket(h.absolutePos(P),h.absolutePos(Q));h.assertFalse(SuperGlueHandler.select(player,packet),"Must hold actual glue");var adventure=h.makeMockServerPlayer(GameType.ADVENTURE);adventure.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(AllItems.SUPER_GLUE));adventure.setPos(player.position());h.assertFalse(SuperGlueHandler.select(adventure,packet),"Adventure mayBuild restriction");h.assertTrue(nearby(h).isEmpty(),"No forged entities");h.succeed();}
    @GameTest public void creativeAreaSelectionDoesNotDamageGlue(GameTestHelper h){stones(h);var player=h.makeMockPlayer(GameType.CREATIVE);GameType.CREATIVE.updatePlayerAbilities(player.getAbilities());player.setPos(player(h).position());player.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(AllItems.SUPER_GLUE));h.assertTrue(SuperGlueHandler.select(player,new SuperGlueSelectionPacket(h.absolutePos(P),h.absolutePos(Q))),"Creative area");h.assertValueEqual(player.getMainHandItem().getDamageValue(),0,"Creative charge preserved");h.succeed();}
    @GameTest public void drillWorkingFaceRejectsGlueButRearFaceConnects(GameTestHelper h){h.setBlock(P,AllBlocks.MECHANICAL_DRILL.defaultBlockState().setValue(net.minecraft.world.level.block.state.properties.BlockStateProperties.FACING,Direction.EAST));h.setBlock(Q,Blocks.STONE);h.setBlock(P.west(),Blocks.STONE);h.assertFalse(SuperGlueEntity.isValidFace(h.getLevel(),h.absolutePos(P),Direction.EAST),"Unsupported working face");var front=SuperGlueSelectionHelper.searchGlueGroup(h.getLevel(),h.absolutePos(P),h.absolutePos(Q),false);h.assertTrue(front==null||!front.contains(h.absolutePos(Q)),"Search does not cross drill front");h.assertTrue(SuperGlueSelectionHelper.searchGlueGroup(h.getLevel(),h.absolutePos(P),h.absolutePos(P.west()),false).contains(h.absolutePos(P.west())),"Rear face can be collected");h.succeed();}
    @GameTest public void sourceGlueBoundsSurviveNativeEntitySaveLoad(GameTestHelper h){stones(h);var original=glue(h);var out=TagValueOutput.createWithContext(ProblemReporter.DISCARDING,h.getLevel().registryAccess());h.assertTrue(original.saveAsPassenger(out),"Native entity serialization");var restored=EntityType.loadEntityRecursive(out.buildResult(),h.getLevel(),new EntitySpawnRequest(EntitySpawnReason.LOAD,false),EntityProcessor.NOP);h.assertTrue(restored instanceof SuperGlueEntity,"Original create:super_glue entity ID");h.assertValueEqual(restored.getBoundingBox(),original.getBoundingBox(),"From/To relative bounds restored exactly");h.assertValueEqual(restored.position(),original.position(),"Restored center position");h.succeed();}
    @GameTest public void staleCachedEntityCannotKeepRemovedFacesGlued(GameTestHelper h){stones(h);var entity=glue(h);var cache=new HashSet<SuperGlueEntity>();h.assertTrue(SuperGlueEntity.isGlued(h.getLevel(),h.absolutePos(P),Direction.EAST,cache),"Cached glue");entity.discard();h.assertFalse(SuperGlueEntity.isGlued(h.getLevel(),h.absolutePos(P),Direction.EAST,cache),"Removed cache entry ignored");h.succeed();}
    @GameTest public void croppedVolumesOnlyRetainConnectionsAcrossAtLeastTwoBlocks(GameTestHelper h){stones(h);glue(h);h.assertTrue(SuperGlueEntity.collectCropped(h.getLevel(),new AABB(h.absolutePos(P))).isEmpty(),"One-block crop has no connection");var cropped=SuperGlueEntity.collectCropped(h.getLevel(),SuperGlueEntity.span(h.absolutePos(P),h.absolutePos(Q)));h.assertValueEqual(cropped.size(),1,"Two-block crop retained");h.assertTrue(cropped.getFirst().contains(h.absolutePos(P))&&cropped.getFirst().contains(h.absolutePos(Q)),"Both captured centers");h.succeed();}
    @GameTest public void realBlockItemPlacementAppliesOffhandGlueOnce(GameTestHelper h){h.setBlock(P,Blocks.STONE);var player=player(h);player.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.STONE,2));player.setItemInHand(InteractionHand.OFF_HAND,new ItemStack(AllItems.SUPER_GLUE));var support=h.absolutePos(P);var point=Vec3.atCenterOf(support).add(0,0,.5);aim(player,point);var result=player.getMainHandItem().useOn(new UseOnContext(player,InteractionHand.MAIN_HAND,new BlockHitResult(point,Direction.SOUTH,support,false)));h.assertTrue(result.consumesAction(),"Actual vanilla BlockItem placed");h.assertBlockPresent(Blocks.STONE,P.south());h.assertTrue(SuperGlueEntity.isGlued(h.getLevel(),support,Direction.SOUTH,null),"Placement mixin captured original support");h.assertValueEqual(player.getOffhandItem().getDamageValue(),1,"One offhand charge");h.assertValueEqual(player.getMainHandItem().getCount(),1,"One block consumed");h.assertValueEqual(nearby(h).size(),1,"One automatically created volume");h.succeed();}
    @GameTest public void itemPlacementWithoutGlueKeepsOrdinaryVanillaBehavior(GameTestHelper h){h.setBlock(P,Blocks.STONE);var player=player(h);player.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.STONE));player.setItemInHand(InteractionHand.OFF_HAND,ItemStack.EMPTY);var support=h.absolutePos(P);player.getMainHandItem().useOn(new UseOnContext(player,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(support).add(0,0,.5),Direction.SOUTH,support,false)));h.assertBlockPresent(Blocks.STONE,P.south());h.assertTrue(nearby(h).isEmpty(),"No glue for ordinary placement");h.succeed();}
    @GameTest public void removalRequiresHeldGlueAndAnActualRayToTheVolume(GameTestHelper h){stones(h);var entity=glue(h);var player=player(h);var packet=new SuperGlueRemovalPacket(entity.getId(),h.absolutePos(P));player.setYRot(0);player.setXRot(0);h.assertFalse(SuperGlueHandler.remove(player,packet),"Looking away cannot remove an area");aim(player,entity.getBoundingBox().getCenter());h.assertTrue(SuperGlueHandler.remove(player,packet),"Actual selected volume removed");h.assertTrue(entity.isRemoved(),"Entity discarded");h.assertValueEqual(player.getMainHandItem().getDamageValue(),0,"Removal is free");h.succeed();}
    @GameTest public void searchesNeverRequestAChunkForAnUnloadedSelection(GameTestHelper h){var pos=new BlockPos(100000,20,100000);h.assertTrue(h.getLevel().getChunkSource().getChunkNow(pos.getX()>>4,pos.getZ()>>4)==null,"Distant chunk initially absent");h.assertTrue(SuperGlueSelectionHelper.searchGlueGroup(h.getLevel(),pos,pos.east(),true)==null,"Unloaded selection rejected");h.assertTrue(h.getLevel().getChunkSource().getChunkNow(pos.getX()>>4,pos.getZ()>>4)==null,"Search did not force chunk");h.succeed();}
    @GameTest public void externalMovementDiscardsGlueInsteadOfMovingItsConnections(GameTestHelper h){var entity=glue(h);h.assertFalse(entity.hurtServer(h.getLevel(),h.getLevel().damageSources().generic(),5),"Ordinary damage does not remove glue");entity.move(MoverType.PISTON,new Vec3(.1,0,0));h.assertTrue(entity.isRemoved(),"Source external displacement removes glue");h.succeed();}
}
